#!/bin/bash
# PreToolUse guard for Claude Code (wired in .claude/settings.json).
# Exit 2 blocks the tool call and shows the message to Claude.
#  1. project.pbxproj is generated by XcodeGen — never edit it by hand.
#  2. main changes only through merged PRs — no direct or force push.

input=$(cat)
tool=$(jq -r '.tool_name // empty' <<<"$input")

block() {
    echo "Blocked by .claude/hooks/guard.sh: $1" >&2
    exit 2
}

case "$tool" in
    Edit|Write|MultiEdit|NotebookEdit)
        path=$(jq -r '.tool_input.file_path // .tool_input.notebook_path // empty' <<<"$input")
        if [[ "$path" == *project.pbxproj ]]; then
            block "project.pbxproj is generated. Edit project.yml, then run 'xcodegen generate'."
        fi
        ;;
    Bash)
        cmd=$(jq -r '.tool_input.command // empty' <<<"$input")
        if grep -Eq '(sed -i|perl -[a-z]*i|>>?)[^|;&]*project\.pbxproj' <<<"$cmd"; then
            block "project.pbxproj is generated. Edit project.yml, then run 'xcodegen generate'."
        fi
        if grep -Eq '(^|[;&|[:space:]])git[[:space:]]+push' <<<"$cmd"; then
            push=$(grep -Eo 'git[[:space:]]+push[^;&|]*' <<<"$cmd")
            if grep -Eq '(--force|--force-with-lease|[[:space:]]-[a-zA-Z]*f[a-zA-Z]*([[:space:]]|$)|[[:space:]]\+)' <<<"$push"; then
                block "force push is not allowed. Ask Mert if history really must be rewritten."
            fi
            if grep -Eq '([[:space:]:]|refs/heads/)main([[:space:]]|$)' <<<"$push"; then
                block "pushing to main directly is not allowed. Push a branch and open a PR; merge only after Mert approves."
            fi
            # `git push` / `git push origin` (no refspec) while on main pushes main.
            positional=0
            for word in ${push#*push}; do
                [[ "$word" == -* ]] || positional=$((positional + 1))
            done
            if (( positional < 2 )) \
               && [[ "$(git -C "${CLAUDE_PROJECT_DIR:-.}" branch --show-current 2>/dev/null)" == "main" ]]; then
                block "you are on main; this push would update main. Create a branch first."
            fi
        fi
        ;;
esac
exit 0
